import cv2,numpy as np
from scipy.ndimage import distance_transform_edt,binary_erosion
T=cv2.imread('/app/target.png',0)<128
A=cv2.imread('/app/output/actual.png',0)<128
for n in [1,2,3,4,5]:
 for kind in ['inner','morph']:
  if kind=='inner': eT=T&~binary_erosion(T,iterations=n);eA=A&~binary_erosion(A,iterations=n)
  else: eT=cv2.morphologyEx(T.astype('uint8'),cv2.MORPH_GRADIENT,np.ones((n*2+1,n*2+1),np.uint8))>0;eA=cv2.morphologyEx(A.astype('uint8'),cv2.MORPH_GRADIENT,np.ones((n*2+1,n*2+1),np.uint8))>0
  dT=distance_transform_edt(~eT);dA=distance_transform_edt(~eA)
  for tol in [4,4.5,5]:
   p=(dT[eA]<=tol).mean();r=(dA[eT]<=tol).mean(); f=2*p*r/(p+r)
   if abs(f-.741)<.03: print(n,kind,tol,round(p,3),round(r,3),round(f,3))
